CREATE TABLE public.scans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), url text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done','failed')), error text, results jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.scans TO authenticated;
GRANT ALL ON public.scans TO service_role;
ALTER TABLE public.scans ENABLE ROW LEVEL SECURITY;
CREATE POLICY scans_select ON public.scans FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY scans_insert ON public.scans FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY scans_update ON public.scans FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY scans_delete ON public.scans FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX scans_owner ON public.scans(user_id,created_at DESC);
CREATE TABLE public.policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), scan_id uuid NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(scan_id,user_id) REFERENCES public.scans(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.policies TO authenticated;
GRANT ALL ON public.policies TO service_role;
ALTER TABLE public.policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY policies_select ON public.policies FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY policies_insert ON public.policies FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY policies_update ON public.policies FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY policies_delete ON public.policies FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX policies_owner_scan ON public.policies(user_id,scan_id,created_at DESC);
CREATE TABLE public.trust_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), scan_id uuid NOT NULL UNIQUE, slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9-]{3,60}$'), app_name text NOT NULL, summary jsonb NOT NULL, published boolean NOT NULL DEFAULT false, last_scan_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(scan_id,user_id) REFERENCES public.scans(id,user_id) ON DELETE CASCADE);
GRANT SELECT, INSERT, UPDATE, DELETE ON public.trust_pages TO authenticated;
GRANT ALL ON public.trust_pages TO service_role;
ALTER TABLE public.trust_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY trust_select ON public.trust_pages FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY trust_insert ON public.trust_pages FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
CREATE POLICY trust_update ON public.trust_pages FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE POLICY trust_delete ON public.trust_pages FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE INDEX trust_owner ON public.trust_pages(user_id);
CREATE TABLE public.public_trust_pages (slug text PRIMARY KEY, app_name text NOT NULL, last_scan_at timestamptz NOT NULL, summary jsonb NOT NULL, published boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.public_trust_pages TO anon, authenticated;
GRANT ALL ON public.public_trust_pages TO service_role;
ALTER TABLE public.public_trust_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_published_only ON public.public_trust_pages FOR SELECT TO anon,authenticated USING (published = true);
CREATE FUNCTION public.sync_public_trust_page() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE clean_summary jsonb;
BEGIN
IF TG_OP = 'DELETE' THEN DELETE FROM public.public_trust_pages WHERE slug = OLD.slug; RETURN OLD; END IF;
IF TG_OP = 'UPDATE' AND OLD.slug <> NEW.slug THEN DELETE FROM public.public_trust_pages WHERE slug = OLD.slug; END IF;
IF NOT NEW.published THEN DELETE FROM public.public_trust_pages WHERE slug = NEW.slug; RETURN NEW; END IF;
IF NOT EXISTS (SELECT 1 FROM public.scans WHERE id = NEW.scan_id AND user_id = NEW.user_id AND status = 'done') THEN RAISE EXCEPTION 'Scan is not publishable'; END IF;
SELECT jsonb_build_object('services', coalesce((SELECT jsonb_agg(jsonb_build_object('name',x->>'name','category',x->>'category')) FROM jsonb_array_elements(coalesce(NEW.summary->'services','[]'::jsonb)) x),'[]'::jsonb),'cookies',jsonb_build_object('total',coalesce((NEW.summary->'cookies'->>'total')::integer,0),'secure',coalesce((NEW.summary->'cookies'->>'secure')::integer,0)),'headers',coalesce((SELECT jsonb_agg(jsonb_build_object('name',x->>'name','present',coalesce((x->>'present')::boolean,false))) FROM jsonb_array_elements(coalesce(NEW.summary->'headers','[]'::jsonb)) x),'[]'::jsonb)) INTO clean_summary;
INSERT INTO public.public_trust_pages(slug,app_name,last_scan_at,summary,published) VALUES(NEW.slug,NEW.app_name,NEW.last_scan_at,clean_summary,true) ON CONFLICT(slug) DO UPDATE SET app_name=excluded.app_name,last_scan_at=excluded.last_scan_at,summary=excluded.summary,published=true;
RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.sync_public_trust_page() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER sync_public_trust AFTER INSERT OR UPDATE OR DELETE ON public.trust_pages FOR EACH ROW EXECUTE FUNCTION public.sync_public_trust_page();